import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid customer, date, and lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  assert.equal(result.ok, true);
  assert.deepEqual(result.value, {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 2,
        unitPrice: 8500,
        vatRate: 21,
      },
    ],
  });
});

test('createInvoice handles multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 1 },
      { sku: 'HOST-MONTH', qty: 12 },
    ],
  });

