import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid customer, date, and lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  assert.equal(result.ok, true);
  assert.deepEqual(result.value, {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 2,
        unitPrice: 8500,
        vatRate: 21,
      },
    ],
  });
});

test('createInvoice handles multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 1 },
      { sku: 'HOST-MONTH', qty: 12 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.deepEqual(result.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 3,
    unitPrice: 8500,
    vatRate: 21,
  });
  assert.deepEqual(result.value.lines[1], {
    sku: 'ICON-SET',
    name: 'Icon set (24 icons)',
    qty: 1,
    unitPrice: 980,
    vatRate: 21,
  });
  assert.deepEqual(result.value.lines[2], {
    sku: 'HOST-MONTH',
    name: 'Website hosting (month)',
    qty: 12,
    unitPrice: 1500,
    vatRate: 21,
  });
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice returns DATE_INVALID for malformed date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '10/07/2026',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice returns DATE_INVALID for invalid date value', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice returns DATE_INVALID for missing date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice returns NO_LINES for missing lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: undefined,
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice returns QTY_INVALID for zero quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice returns QTY_INVALID for negative quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice returns QTY_INVALID for fractional quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice returns UNKNOWN_SKU for invalid SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice fails on first invalid line when multiple exist', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'UNKNOWN', qty: 1 },
      { sku: 'HOST-MONTH', qty: 1 },
    ],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice includes products with different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  const originalLines = JSON.stringify(lines);

  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });

  assert.equal(JSON.stringify(lines), originalLines);
});

test('lineTotal multiplies qty by unitPrice', () => {
  const line = { qty: 5, unitPrice: 1000 };
  assert.equal(lineTotal(line), 5000);
});

test('lineTotal with single unit', () => {
  const line = { qty: 1, unitPrice: 8500 };
  assert.equal(lineTotal(line), 8500);
});

test('lineTotal with large quantities', () => {
  const line = { qty: 1000, unitPrice: 50 };
  assert.equal(lineTotal(line), 50000);
});

test('invoiceTotals returns subtotal and total for single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 2, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 17000,
    total: 17000,
  });
});

test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 3, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
      { sku: 'ICON-SET', qty: 2, unitPrice: 980, name: 'Icon set (24 icons)', vatRate: 21 },
      { sku: 'HOST-MONTH', qty: 1, unitPrice: 1500, name: 'Website hosting (month)', vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 3 * 8500 + 2 * 980 + 1500);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals with empty lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 0,
    total: 0,
  });
});

test('invoiceTotals with various price points', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'STICKER', qty: 100, unitPrice: 50, name: 'Sticker sheet', vatRate: 21 },
      { sku: 'LOGO-PACK', qty: 1, unitPrice: 120000, name: 'Logo package', vatRate: 21 },
      { sku: 'PHOTO-LIC', qty: 5, unitPrice: 996, name: 'Stock photo licence', vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const expected = 100 * 50 + 1 * 120000 + 5 * 996;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'ICON-SET', qty: 1 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.deepEqual(result.value.lines[1], {
    sku: 'ICON-SET',
    name: 'Icon set (24 icons)',
    qty: 1,
    unitPrice: 980,
    vatRate: 21,
  });
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 5);
});

test('addLine with multiple existing lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'ICON-SET', qty: 1 },
    ],
  }).value;

  const result = addLine(invoice, { sku: 'ICON-SET', qty: 2 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].qty, 2);
  assert.equal(result.value.lines[1].qty, 3);
});

test('addLine returns NOT_DRAFT if invoice is not draft', () => {
