    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 2, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'ICON-SET', qty: 1 });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('addLine returns QTY_INVALID for invalid quantity', () => {
